          :label="copy.app.settings"
          variant="quiet"
          @click="settingsOpen = !settingsOpen"
        >
          <UserRound :size="18" :stroke-width="1.5" />
        </HmIconButton>

        <HmFloatingWindow
          v-if="settingsOpen"
          class="user-settings__panel"
          initial-placement="bottom-end"
          :label="copy.app.settings"
          size="sm"
        >
          <template #titlebar>
            <header class="user-settings__header">
